/** Accessible, bounded UI for the three primary evidence perspectives. */
import { periodDigest, contributorPortrait, releaseDetails, releaseLandscape, codebasePortrait, windowOf, briefingText } from './perspectives.js?v=git-contribution-level-20261106-1';
import { makeIntensityScale, intensityStyle, intensityLegend } from './value-colour.js?v=git-contribution-level-20261106-1';
import { coReleasePatterns, coReleaseEvidence } from './co-release.js?v=git-contribution-level-20261106-1';
import { targetUrl } from './route-state.js?v=git-contribution-level-20261106-1';
import { deploymentOverviewPanel, deploymentReleasePanel, deploymentPeriodPanel, deploymentContributorPanel, deploymentExplorer, deploymentBriefing } from './deployment-view.js?v=git-contribution-level-20261106-1';

const e=value=>String(value??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const n=new Intl.NumberFormat('en-GB',{maximumFractionDigits:1});
const f=v=>Number.isFinite(v)?n.format(v):'—';
const p=v=>Number.isFinite(v)?`${n.format(v*100)}%`:'—';
const day=v=>v?new Date(`${v}T12:00:00Z`).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}):'Unknown date';
const type=v=>({major:'Major',minor:'Minor',patch:'Patch',prerelease:'Prerelease',baseline:'Baseline',unclassified:'Unclassified',divergent:'Parallel history','same-version':'Same version'})[v]||'Unclassified';
const clamp=(v,min,max)=>Math.min(max,Math.max(min,v));
const unique=values=>[...new Set(values)];
const shiftDate=(date,n)=>new Date(Date.parse(`${date}T00:00:00Z`)+n*86400000).toISOString().slice(0,10);
const monthEnd=month=>new Date(Date.UTC(+month.slice(0,4),+month.slice(5,7),0)).toISOString().slice(0,10);
const dateAtWeek=date=>{const at=Date.parse(`${date}T00:00:00Z`),weekday=(new Date(at).getUTCDay()+6)%7;return new Date(at-weekday*86400000).toISOString().slice(0,10);};
const bar=(v,max,cls='')=>`<span class="primary-mini-track"><span class="primary-mini-fill ${cls}" style="width:${max>0?clamp(v/max*100,0,100):0}%"></span></span>`;
const href=(index,change)=>e(targetUrl(index.navigation?.path||'./index.html',index.navigation?.ui||{},index.navigation?.groups||index.groups,index.navigation?.datasetId,change));
const tagButton=(index,r,text=r.tag)=>`<a class="primary-inline-link" href="${href(index,{view:'observatory',release:r.hash})}" data-action="primary-open-release" data-hash="${e(r.hash)}">${e(text)} <span aria-hidden="true">↗</span></a>`;
const whoButton=(index,id)=>`<a class="primary-inline-link" href="${href(index,{view:'contributors',person:index.groups.find(g=>g.id===id)?.emails?.[0],tab:'delivery'})}" data-action="primary-open-person" data-person="${e(id)}">${e(index.groups.find(g=>g.id===id)?.displayName||'Unknown contributor')}</a>`;
const stat=(value,label,note='')=>`<div class="primary-stat"><strong>${e(value)}</strong><span>${e(label)}</span>${note?`<small>${e(note)}</small>`:''}</div>`;
const empty=(title,detail)=>`<div class="primary-quiet"><strong>${e(title)}</strong><p>${e(detail)}</p></div>`;
const chrome=(label,sub)=>`<div class="primary-heading"><span class="primary-eyebrow">${e(label)}</span><h2>${e(sub)}</h2></div>`;
const caption=text=>`<p class="primary-explainer">${e(text)}</p>`;
const select=(id,values,selected,attr='')=>`<select id="${id}" class="primary-select" ${attr}>${values.map(v=>`<option value="${e(v.value)}" ${String(v.value)===String(selected)?'selected':''}>${e(v.label)}</option>`).join('')}</select>`;
const card=(title,body,eyebrow='')=>`<section class="primary-panel"><div class="primary-card-heading">${eyebrow?`<span class="primary-eyebrow">${e(eyebrow)}</span>`:''}<h3>${e(title)}</h3></div>${body}</section>`;
const filterSentence=index=>`Git author timestamps for activity · tag/GitHub publication events for releases · ${index.policy.includeMerges?'merges included':'merges excluded'} · ${index.policy.includeReverts?'reverts included':'reverts excluded'}`;

function timelineGrid(bins,lanes,{action='primary-bin',dateAttr='data-bin',title='Chronological observations'}={}) {
  if(!bins.length)return empty('Nothing to plot yet','There are no recorded events in this time span.');
  const max=Math.max(1,...bins.map(b=>b.count??b.commits??0));
  const peopleMax=Math.max(1,...bins.map(b=>b.people??0));
  const areaMax=Math.max(1,...bins.map(b=>b.areas??0));
  const values={count:max,commits:max,people:peopleMax,areas:areaMax,drivers:Math.max(1,...bins.map(b=>b.drivers??0))};
  return `<div class="primary-landscape" aria-label="${e(title)}"><div class="primary-lane-labels">${lanes.map(l=>`<span>${e(l.label)}</span>`).join('')}<span class="primary-landscape-time">Earlier → Recent</span></div><div class="primary-landscape-scroll"><div class="primary-landscape-columns" style="--bars:${bins.length}">${bins.map(b=>`<button type="button" class="primary-landscape-column" data-action="${action}" ${dateAttr}="${e(b.key)}" title="${e(`${b.key}: ${b.count??b.commits??0} ${lanes[0].label.toLowerCase()}; select this period`)}" aria-label="${e(`Inspect ${b.key}`)}">${lanes.map(l=>`<span class="primary-landscape-slot"><i style="height:${b[l.key]>0?clamp(6+94*b[l.key]/(values[l.key]||1),6,100):0}%" class="${e(l.className||'')}"></i></span>`).join('')}<small>${e(b.key)}</small></button>`).join('')}</div></div></div>`;
}

function releaseAnatomy(index,selectedHash){
  const details=releaseDetails(index,selectedHash);
  if(!details)return empty('Select a release','Choose a tag in the landscape or release index to see its complete contents.');
  const {release:r,commits}=details;
  const rows=r.members.filter(m=>m.commits>0).sort((a,b)=>b.commits-a.commits);
  const total=Math.max(1,r.eligibleIntroduced);
  const people=rows.slice(0,12).map(m=>`<div class="primary-person-row"><span>${whoButton(index,m.id)}${r.driver.groupId===m.id?'<span class="primary-driver-chip">Drove release</span>':''}</span>${bar(m.commits,total)}<strong>${f(m.commits)}</strong><small>${p(m.commits/total)}</small></div>`).join('');
  const areas=r.areaTouches.slice().sort((a,b)=>b[1]-a[1]).slice(0,10);
  const maxArea=Math.max(1,...areas.map(x=>x[1]));
  const counts=Object.entries(r.categoryCounts).filter(([,v])=>v>0).sort((a,b)=>b[1]-a[1]).slice(0,6);
  return `<section class="primary-anatomy primary-panel" id="primary-release-anatomy" tabindex="-1">
    <div class="primary-anatomy-head"><div><span class="primary-eyebrow">RELEASE ANATOMY · COMPLETE TAG ANCESTRY</span><h3>${e(r.tag)}</h3><p>${e(r.github?.title&&r.github.title!==r.tag?r.github.title:'Tagged delivery snapshot')} · ${e(day(r.date))} · ${e(type(r.kind))}</p></div><div class="primary-anatomy-actions"><span class="primary-kind">${e(type(r.kind))}</span>${r.github?.url&&/^https:\/\/github\.com\//.test(r.github.url)?`<a href="${e(r.github.url)}" target="_blank" rel="noopener noreferrer">GitHub ↗</a>`:''}</div></div>
    <div class="primary-facts">${stat(r.baseline?'Baseline':f(r.eligibleIntroduced),'Included commits',r.baseline?'Not an incremental release':r.totalIntroduced!==r.eligibleIntroduced?'Commit policy excludes some records':'Git tag-defined')}${stat(f(r.contributors),'Contributors')}${stat(f(r.areas),'Codebase areas')}${stat(f(r.paths),'Distinct paths')}</div>
    <div class="primary-inspector-context"><span><strong>Driver:</strong> ${r.driver.groupId!=null?whoButton(index,r.driver.groupId):e(r.driver.name||'Not identified')}</span><span><strong>Previous tag:</strong> ${e(r.previousTag||'No preceding tagged ancestor')}</span><span><strong>Date source:</strong> ${e(r.dateSource||'Unknown')}</span></div>
    ${!r.lineageComplete?'<p class="primary-warning">Ancestry is incomplete in the imported refs. Introduced-change counts may be incomplete.</p>':''}
    <div class="primary-two-col"><div class="primary-inset"><h4>Who authored its changes?</h4>${people||empty('No matching included changes','Check the merge/revert policy and imported refs.')}${rows.length>12?`<p class="primary-muted">${rows.length-12} further contributors; use Explore Evidence for the full matrix.</p>`:''}<p class="primary-muted">Commit share uses the complete included release (under the stated commit policy). The driver role is independent.</p></div><div class="primary-inset"><h4>Where did they land?</h4>${areas.map(([name,count])=>`<div class="primary-area-row"><a href="${href(index,{view:'codebase',area:name})}" data-action="primary-open-area" data-area="${e(name)}">${e(name)}</a>${bar(count,maxArea)}<span>${f(count)}</span></div>`).join('')||'<p class="primary-muted">No files in this release.</p>'}<h4 class="primary-subtitle">Recorded change categories</h4><div class="primary-tags">${counts.map(([k,v])=>`<span>${e(k)} · ${f(v)}</span>`).join('')||'No categories recorded'}</div><p class="primary-muted">Categories are inferred from commit subjects, not verified intent.</p></div></div>
    ${deploymentReleasePanel(index,r)}
    ${r.github?.body?`<details class="primary-notes"><summary>Read published release notes</summary><div class="primary-notes-body">${e(r.github.body)}</div></details>`:''}
    <details class="primary-notes"><summary>Inspect ${f(r.commits.length)} included commits (latest 40 shown)</summary><div class="primary-commit-list">${commits.map(c=>`<div><code>${e(c.hash.slice(0,8))}</code><span>${e(day(c.date))}</span>${whoButton(index,c.groupId)}<span class="primary-commit-subject">${e(c.subject)}</span></div>`).join('')||'<p>No matching commit detail in imported history.</p>'}</div></details>
    <div class="primary-card-footer"><a class="button soft" href="${href(index,{view:'periods',from:r.date?shiftDate(r.date,-6):null,to:r.date?shiftDate(r.date,7):null})}" data-action="primary-release-period" data-date="${e(r.date||'')}">Explore surrounding fortnight →</a><button type="button" class="button outline" data-action="primary-evidence-release" data-hash="${e(r.hash)}">Open full release evidence ↗</button></div>
  </section>`;
}

function observatory(index,ui){
  const all=releaseLandscape(index);
  if(!all.total)return `${chrome('01 / RELEASE OBSERVATORY','The shape of delivery.')} ${empty('No matched release tags','Re-import reachable Git tags to enable the release-first perspective. You can still explore authored activity in Periods.')}`;
  const years=[...new Set(all.releases.map(r=>r.date.slice(0,4)))].reverse();
  const binFor=date=>all.granularity==='quarter'?`${date.slice(0,4)} Q${Math.floor((+date.slice(5,7)-1)/3)+1}`:all.granularity==='month'?date.slice(0,7):dateAtWeek(date);
  const list=all.releases.filter(r=>(ui.releaseType==='all'||r.kind===ui.releaseType)&&(ui.releaseYear==='all'||r.date.startsWith(ui.releaseYear))&&(!ui.releaseBin||binFor(r.date)===ui.releaseBin)&&(String(r.tag).toLowerCase().includes((ui.releaseQuery||'').toLowerCase()))).reverse();
  const pages=Math.max(1,Math.ceil(list.length/24)),page=clamp(ui.releasePage||0,0,pages-1);
  const shown=list.slice(page*24,page*24+24);
  const chosen=list.find(r=>r.hash===ui.releaseHash)||list[0]||null;
  const periods=all.bins;
  const palette=all.types.filter(([kind])=>kind!=='baseline').slice(0,7);
  const med=all.medianInterval;
  let change=null;
  if(all.releases.length>=12 && all.previousCadence!=null && all.recentCadence!=null && Math.abs(all.recentCadence-all.previousCadence)>=Math.max(2,all.previousCadence*.25)){
    change=`The median calendar gap between successive release events changed from ${f(all.previousCadence)} to ${f(all.recentCadence)} days across the earlier and later halves of the observed release history. A change in cadence is not a measure of quality.`;
  }
  const cohortBy=['type','driver','year'].includes(ui.cohortBy)?ui.cohortBy:'type';
  const labelForCohort=r=>cohortBy==='driver'
    ? r.driver.groupId!=null ? index.groups.find(g=>g.id===r.driver.groupId)?.displayName||'Unknown driver'
      : r.driver.name ? `Unmatched: ${r.driver.name}` : 'Driver unknown'
    : cohortBy==='year'?r.date.slice(0,4):r.kind;
  const grouped=new Map();for(const r of all.releases.filter(r=>!r.baseline)){
    const k=labelForCohort(r),a=grouped.get(k)||[];a.push(r);grouped.set(k,a);
  }
  const cohorts=[...grouped].sort((a,b)=>b[1].length-a[1].length).slice(0,8);
  const median=values=>{const a=values.filter(Number.isFinite).sort((x,y)=>x-y);const i=Math.floor(a.length/2);return a.length?(a.length%2?a[i]:(a[i-1]+a[i])/2):null;};
  return `${chrome('01 / RELEASE OBSERVATORY','The shape of delivery.')}<p class="primary-lede">Start with what shipped. Follow the changes, people and codebase areas behind each tagged release.</p>
    <div class="primary-facts">${stat(f(all.total),'Tagged releases','From imported refs')}${stat(f(all.contributors),'Release contributors','Recorded Git authors')}${stat(f(all.drivers),'Matched release drivers','GitHub or annotated tag')}${stat(med==null?'—':`${f(med)} days`,'Median release interval','Based on event dates')}</div>
    ${deploymentOverviewPanel(index)}
    ${card('The release landscape',`<p class="primary-muted">Aligned lanes describe release frequency, contributor appearances and summed codebase reach. Select a time bucket to narrow the release index; the release anatomy remains complete.</p>${timelineGrid(periods,[{label:'Releases',key:'count'},{label:'Contributor appearances',key:'people',className:'alt'},{label:'Codebase-area occurrences',key:'areas',className:'gold'}],{action:'primary-observatory-bin',dateAttr:'data-bin',title:'Release events grouped by time'})}<div class="primary-row between"><span class="primary-muted">${e(all.granularity)} buckets · earliest to latest · ${f(periods.length)} observed buckets</span><button class="primary-inline-link" type="button" data-action="primary-reset-release-search">Show all releases</button></div>`,'DELIVERY EVOLUTION')}
    <div class="primary-two-col"><div>${card('Release mix',`<div class="primary-type-list">${palette.map(([k,v])=>`<div><span>${e(type(k))}</span>${bar(v,Math.max(1,...palette.map(x=>x[1])))}<strong>${f(v)}</strong></div>`).join('')}</div><p class="primary-muted">SemVer labels identify version transitions, not their importance.</p>`,'RELEASE TYPES')}</div><div>${card("What's notable?",`<div class="primary-observation"><span class="primary-obs-mark">✳</span><p>${e(change||'The release history is ready for investigation. Select a period or release to compare who contributed, what changed and which people drove delivery.')}</p></div><a class="primary-inline-link" href="${href(index,{view:'periods',from:ui.periodFrom,to:ui.periodTo})}" data-action="primary-nav" data-to="periods">Explore an arbitrary period ↗</a>`,'EVIDENCE-LED CONTEXT')}</div></div>
    ${card('Compare release cohorts',`<div class="primary-row between"><p class="primary-muted">Group comparable incremental releases, then inspect their typical size and people/area breadth. This is composition, not a ranking. Baselines excluded.</p><label>Group by ${select('primary-cohort-by',[{value:'type',label:'Version transition'},{value:'driver',label:'Matched / recorded driver'},{value:'year',label:'Release year'}],cohortBy)}</label></div><div class="primary-cohorts">${cohorts.map(([kind,rs])=>`<div class="primary-cohort"><span>${e(cohortBy==='type'?type(kind):kind)}</span><strong>${f(rs.length)} releases</strong><small>Median ${f(median(rs.map(r=>r.eligibleIntroduced)))} commits · ${f(median(rs.map(r=>r.contributors)))} contributors · ${f(median(rs.map(r=>r.areas)))} areas</small>${cohortBy==='type'?`<button class="primary-inline-link" type="button" data-action="primary-filter-release-type" data-type="${e(kind)}">Inspect this release kind ↗</button>`:''}</div>`).join('')}</div>${grouped.size>cohorts.length?`<p class="primary-muted">Showing ${cohorts.length} of ${grouped.size} cohorts; use the release index to inspect specific tags.</p>`:''}`,'COHORT ANALYSIS')}
    ${card('Browse releases',`${ui.releaseBin?`<p class="primary-filter-chip">Viewing bucket ${e(ui.releaseBin)} <button type="button" data-action="primary-reset-release-bin">Clear filter ×</button></p>`:''}<div class="primary-controls primary-release-controls"><label>Kind ${select('primary-release-type',[{label:'All release kinds',value:'all'},...all.types.map(([k])=>({label:type(k),value:k}))],ui.releaseType)}</label><label>Year ${select('primary-release-year',[{value:'all',label:'All years'},...years.map(y=>({value:y,label:y}))],ui.releaseYear)}</label><label>Find a tag <input id="primary-release-query" class="primary-input" placeholder="Filter tag names…" value="${e(ui.releaseQuery||'')}"></label></div><div class="primary-release-list">${shown.map(r=>`<a href="${href(index,{view:'observatory',release:r.hash})}" class="primary-release-entry ${r.hash===chosen?.hash?'selected':''}" data-action="primary-select-release" data-hash="${e(r.hash)}" ${r.hash===chosen?.hash?'aria-current="true"':''}><span class="primary-release-symbol">${r.kind==='major'?'◆':r.kind==='minor'?'◈':'●'}</span><strong>${e(r.tag)}</strong><small>${e(day(r.date))}</small><span>${f(r.eligibleIntroduced)} commits</span><span>${f(r.contributors)} people</span><em>${e(type(r.kind))}</em></a>`).join('')||empty('No releases match','Change the year, type or tag search.')}</div><div class="primary-row between"><span class="primary-muted">${f(list.length)} matching · page ${page+1} of ${pages}</span><div class="primary-pager"><button data-action="primary-release-page" data-page="${page-1}" ${page===0?'disabled':''}>← Newer</button><button data-action="primary-release-page" data-page="${page+1}" ${page>=pages-1?'disabled':''}>Older →</button></div></div>`,'ALL TAGGED HISTORY')}
    ${chosen?releaseAnatomy(index,chosen.hash):empty('No release in this filter','Change the year, type or tag filter to choose a release.')}`;
}

const dateInput=(id,value)=>`<input id="${id}" type="date" class="primary-input" value="${e(value||'')}">`;
const delta=(now,old,unit='')=>old==null?'':`<small class="primary-delta">Previous: ${f(old)}${e(unit)} · ${now===old?'no change':`${now>old?'+':''}${f(now-old)}${e(unit)}`}</small>`;
function periodExplorer(index,ui){
  const window=ui.periodFrom&&ui.periodTo?{from:ui.periodFrom,to:ui.periodTo}:windowOf(index,14);
  const digest=periodDigest(index,window,{comparison:ui.periodComparison,customComparison:{from:ui.compareFrom,to:ui.compareTo},selectedIds:ui.periodSelectedId?[ui.periodSelectedId]:null});
  if(!digest)return empty('Check your dates','The start date must be on or before the end date.');
  const {summary:s,events,comparison:prev,timeline,releases}=digest;
  const max=Math.max(1,...s.areas.map(a=>a[1]));
  const sortedPeople=s.people.slice(0,10), sortedAreas=s.areas.slice(0,9);
  const matrixMax=Math.max(1,...s.personAreas.flatMap(([,arr])=>arr.map(([,v])=>v)));
  const scale=makeIntensityScale(s.personAreas.flatMap(([,arr])=>arr.map(([,v])=>v)),{max:matrixMax});
  const peopled=new Map(s.personAreas.map(([id,list])=>[id,new Map(list)]));
  const focus=ui.periodFocusPerson&&ui.periodFocusArea ? index.activity.filter(c=>c.groupId===ui.periodFocusPerson&&c.date>=window.from&&c.date<=window.to&&c.files.some(f=>f.area===ui.periodFocusArea)) : [];
  const topNotes=releases.filter(r=>r.github?.body).slice(-3).reverse();
  const bucket=timeline.buckets.find(b=>b.key===ui.periodBucket);
  const bucketKey=date=>timeline.granularity==='day'?date:timeline.granularity==='week'?dateAtWeek(date):date.slice(0,7);
  const bucketCommits=bucket?index.activity.filter(c=>c.date>=window.from&&c.date<=window.to&&(!ui.periodSelectedId||c.groupId===ui.periodSelectedId)&&bucketKey(c.date)===bucket.key).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,14):[];
  const bucketReleases=bucket?releases.filter(r=>bucketKey(r.date)===bucket.key):[];
  const diff=prev&&s.spanDays>0?[
    {title:'Authored activity',value:s.commits,prior:prev.summary.commits,note:'Matching commits (author date)'},
    {title:'Release events',value:releases.length,prior:prev.events.releases,note:'Published/tag event dates'},
    {title:'People authoring',value:s.people.length,prior:prev.summary.people.length,note:'Distinct reconciled contributors'},
    {title:'Areas touched',value:s.areas.length,prior:prev.summary.areas.length,note:'Top-level paths with authored activity'},
  ]:[];
  const note=ui.periodComparison==='year'?'Same calendar dates one year earlier (partial/leap-year coverage may differ).':ui.periodComparison==='previous'?'Immediately preceding period of equal calendar-day length.':ui.periodComparison==='custom'?'User-selected comparison window; check differing observation lengths.':'No historical comparison selected.';
  const insights=[];
  if(prev&&digest.comparisonComparable&&s.spanDays>=7&&prev.window.days>=7){
    const diffRates=s.commits/s.spanDays-prev.summary.commits/prev.window.days;
    if(Math.abs(diffRates)>=.3 && Math.max(s.commits,prev.summary.commits)>=8)insights.push(`Recorded author activity changed from ${f(prev.summary.commits*7/prev.window.days)} to ${f(s.commits*7/s.spanDays)} commits per calendar week. This describes recording frequency, not work output.`);
    if(Math.abs(releases.length-prev.events.releases)>=2)insights.push(`${releases.length} release events occurred, compared with ${prev.events.releases} in the comparison window. Release contents can include older authored changes.`);
  }
  return `${chrome('02 / PERIOD EXPLORER','What happened in this window?')}<p class="primary-lede">An interactive retrospective of observed work, delivery milestones, contributors and changed areas.</p>
    ${card('Choose a period',`<div class="primary-period-controls"><div><span class="primary-eyebrow">QUICK WINDOWS</span><div class="primary-preset-row">${[7,14,30,90].map(d=>`<button type="button" data-action="primary-period-preset" data-days="${d}" class="primary-preset ${ui.periodPreset===String(d)?'active':''}">${d} days</button>`).join('')}<button type="button" data-action="primary-period-custom" class="primary-preset ${ui.periodPreset==='custom'?'active':''}">Custom</button></div></div><label>From ${dateInput('primary-period-from',window.from)}</label><label>To ${dateInput('primary-period-to',window.to)}</label><label>Author focus ${select('primary-period-person',[{value:'',label:'All reconciled contributors'},...index.groups.map(g=>({value:g.id,label:g.displayName}))],ui.periodSelectedId||'')}</label><label>Compare against ${select('primary-period-comparison',[{value:'previous',label:'Previous equal-length period'},{value:'year',label:'Same dates last year'},{value:'custom',label:'Another interval'},{value:'none',label:'No comparison'}],ui.periodComparison)}</label></div>${ui.periodComparison==='custom'?`<div class="primary-row"><label>Comparison from ${dateInput('primary-compare-from',ui.compareFrom)}</label><label>Comparison to ${dateInput('primary-compare-to',ui.compareTo)}</label></div>`:''}<p class="primary-muted">${e(note)} · ${e(filterSentence(index))}</p>${prev&&!digest.comparisonComparable?'<p class="primary-warning">The comparison window extends beyond imported history. Zeroes outside observed coverage cannot support a claim of change.</p>':''}${digest.coverage.startsBeforeHistory||digest.coverage.endsAfterHistory?'<p class="primary-warning">Part of this window falls outside the imported observation bounds; zero activity is not proof of inactivity.</p>':''}`,'TIME SCOPE')}
    <div class="primary-facts">${stat(f(s.commits),'Authored commits',`${s.activeDays} calendar dates active`)}${stat(f(s.people.length),'Authored contributors')}${stat(f(events.releases),'Release events','Contents can predate window')}${stat(f(s.areas.length),'Areas touched','From authored changes')}</div>
    ${card('The period, unfolding',`<p class="primary-muted">Aligned daily, weekly or monthly buckets; individual bars represent the chosen time unit, not the same amount of calendar time for every zoom.</p>${timelineGrid(timeline.buckets.map(b=>({...b,count:b.commits,areas:b.releases.length})),[{label:'Authored commits',key:'commits'},{label:'Contributors',key:'people',className:'alt'},{label:'Release events',key:'areas',className:'gold'}],{action:'primary-period-bin',dateAttr:'data-bin',title:'Authored and release events in the period'})}<div class="primary-row between"><small class="primary-muted">Resolution: ${e(timeline.granularity)}. Select a bucket to inspect its events.</small><button class="primary-inline-link" data-action="primary-period-reset" type="button">Reset to full window</button></div>${bucket?`<div class="primary-inset"><h4>${e(bucket.key)} · ${f(bucket.commits)} authored commits · ${f(bucket.releases.length)} release events</h4><div class="primary-bucket-events">${bucketReleases.slice(0,12).map(r=>`<span>${tagButton(index,r)}</span>`).join('')}${bucketCommits.map(c=>`<div><code>${e(c.hash.slice(0,8))}</code> ${whoButton(index,c.groupId)} · ${e(c.subject)}</div>`).join('')||'<p>No authored commits in this bucket under the current focus.</p>'}</div></div>`:''}`,'CHRONOLOGY')}
    <div class="primary-two-col"><div>${card('Who was involved?',`<div class="primary-ranked">${sortedPeople.map(([id,count])=>`<div class="primary-ranked-row"><span>${whoButton(index,id)}</span>${bar(count,Math.max(1,...s.people.map(x=>x[1])))}<strong>${f(count)}</strong></div>`).join('')||empty('No authored commits','Check the date and import scope.')}</div><p class="primary-muted">People here authored commits in the selected dates, irrespective of which tagged releases contain their work.</p>`,'AUTHORED CONTRIBUTIONS')}</div><div>${card('Where did work occur?',`<div class="primary-ranked">${sortedAreas.map(([area,count])=>`<div class="primary-ranked-row"><a href="${href(index,{view:'codebase',area})}" data-action="primary-open-area" data-area="${e(area)}">${e(area)}</a>${bar(count,max)}<strong>${f(count)}</strong></div>`).join('')||empty('No touched files','No file numstat entries in this window.')}</div><p class="primary-muted">Each file touch is counted; shared paths can appear under several people.</p>`,'COMPONENT FOOTPRINT')}</div></div>
    ${card('Who × where',`<p class="primary-muted">Each cell counts authored-file touches by a reconciled contributor in a top-level code area. One zero-aware scale applies to all visible cells. Select a cell to inspect the matching commits.</p>${sortedPeople.length&&sortedAreas.length?`<div class="primary-matrix-scroll"><table class="primary-heat-table"><thead><tr><th>Contributor</th>${sortedAreas.map(([a])=>`<th><a href="${href(index,{view:'codebase',area:a})}" data-action="primary-open-area" data-area="${e(a)}">${e(a)}</a></th>`).join('')}</tr></thead><tbody>${sortedPeople.map(([id])=>`<tr><th>${whoButton(index,id)}</th>${sortedAreas.map(([area])=>{const value=peopled.get(id)?.get(area)||0;return `<td><button type="button" data-action="primary-period-cell" data-person="${e(id)}" data-area="${e(area)}" style="${intensityStyle(value,scale)}" title="${e(`${value} authored file touches in ${area}`)}">${f(value)}</button></td>`;}).join('')}</tr>`).join('')}</tbody></table></div><div class="primary-colour-legend">${intensityLegend(scale)}</div>`:empty('No comparable cells','No authored-file touches recorded in this window.')}${ui.periodFocusPerson&&ui.periodFocusArea?`<div class="primary-selected-evidence"><h4>${e(index.groups.find(g=>g.id===ui.periodFocusPerson)?.displayName||'Contributor')} · ${e(ui.periodFocusArea)}</h4><p>${focus.length} matching commits · first 14 shown</p>${focus.slice(0,14).map(c=>`<div><code>${e(c.hash.slice(0,8))}</code><span>${e(c.date)}</span> ${e(c.subject)}</div>`).join('')||'<p>No matching commits.</p>'}</div>`:''}`,'CONTRIBUTION MAP')}
    ${prev&&digest.comparisonComparable?card('What changed?',`<p class="primary-muted">${e(note)}</p><div class="primary-comparison-grid">${diff.map(v=>`<div><span>${e(v.title)}</span><strong>${f(v.prior)} <span aria-hidden="true">→</span> ${f(v.value)}</strong>${delta(v.value,v.prior)}<small>${e(v.note)}</small></div>`).join('')}</div>${insights.length?`<div class="primary-observations">${insights.map(t=>`<p>✳ ${e(t)}</p>`).join('')}</div>`:'<p class="primary-muted">No material multi-signal change is established in this comparison. The underlying figures remain available above.</p>'}`,'MATCHED-PERIOD COMPARISON'):''}
    ${deploymentPeriodPanel(index,ui)}
    ${card('What shipped in this period?',`<p class="primary-muted">These are release *events* in the window; each release retains its full tag-defined ancestry even if individual changes were authored earlier.</p><div class="primary-releases-compact">${releases.slice(-18).reverse().map(r=>`<div>${tagButton(index,r)}<span>${e(day(r.date))}</span><span>${f(r.eligibleIntroduced)} included commits</span><span>${r.driver.groupId!=null?whoButton(index,r.driver.groupId):e(r.driver.name||'Unattributed driver')}</span></div>`).join('')||empty('No tagged releases','Authored activity can exist without a release event.')}</div>${releases.length>18?`<p class="primary-muted">Latest 18 of ${f(releases.length)} events shown. Use Observatory for all releases.</p>`:''}`,'DELIVERY MILESTONES')}
    ${card('Recorded purpose & evidence',`<p class="primary-muted">"Why" is limited to wording actually recorded in GitHub release notes and commit subjects; Git alone cannot establish underlying decisions or value.</p>${topNotes.map(r=>`<div class="primary-note-excerpt"><strong>${tagButton(index,r)}</strong><p>${e(r.github.body.slice(0,250))}${r.github.body.length>250?'…':''}</p></div>`).join('')||'<p class="primary-muted">No GitHub release notes captured for this period.</p>'}<details class="primary-notes"><summary>Inspect recent authored commits</summary><div class="primary-commit-list">${digest.commits.map(c=>`<div><code>${e(c.hash.slice(0,8))}</code><span>${e(c.date)}</span>${whoButton(index,c.groupId)}<span>${e(c.subject)}</span></div>`).join('')||'No commits in this period.'}</div></details><div class="primary-card-footer"><button type="button" class="button primary" data-action="primary-copy-briefing">Copy period briefing</button><span id="primary-copy-status" role="status" aria-live="polite"></span></div>`,'PURPOSE & PROVENANCE')}`;
}

function weekHeatmap(slots,options={shape:true}){
  const total=slots.flat().reduce((a,b)=>a+b,0);
  const values=slots.flat().map(v=>options.shape&&total?100*v/total:v);
  const scale=makeIntensityScale(values);
  const labels=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
  return `<div class="primary-week-heat" role="img" aria-label="Seven weekday rows, 24 hourly columns; ${options.shape?'share of timed commits':'absolute timed commits'}"><div class="primary-hour-ruler"><span></span>${[0,6,12,18,23].map(h=>`<span>${String(h).padStart(2,'0')}</span>`).join('')}</div>${slots.map((row,d)=>`<div class="primary-hour-row"><strong>${labels[d]}</strong><div>${row.map((value,h)=>`<i style="${intensityStyle(options.shape&&total?100*value/total:value,scale)}" title="${e(`${labels[d]} ${h}:00 · ${value} timed commits${total?` (${(100*value/total).toFixed(1)}%)`:''}`)}"></i>`).join('')}</div></div>`).join('')}</div><p class="primary-muted">${f(total)} timed commits · ${options.shape?'each grid normalised within its contributor':'absolute counts'} · recorded author-local hours</p>`;
}

function coReleasePanel(index,focus,window,ui) {
  const model=coReleasePatterns(index,focus,window);
  const people=model.partners.filter(r=>r.shared>0);
  const sorted=people.slice().sort(ui.coReleaseSort==='overlap'
    ? (a,b)=>(b.overlap??0)-(a.overlap??0)||b.shared-a.shared||a.name.localeCompare(b.name)
    : (a,b)=>b.shared-a.shared||(b.overlap??0)-(a.overlap??0)||a.name.localeCompare(b.name));
  const chosen=model.partners.find(r=>r.id===ui.coReleasePartner)||sorted[0]||model.partners[0];
  const examples=chosen?coReleaseEvidence(index,focus,chosen.id,window):[];
  const myName=index.groups.find(g=>g.id===focus)?.displayName||'Selected contributor';
  const eligibleNote=model.omitted?` ${model.omitted} baseline or incomplete-lineage tag events excluded.`:'';
  return card('People who appear in the same tagged releases',`<p class="primary-muted">Each shared release contains eligible authored commits from <strong>both</strong> contributors. The observation window selects <strong>release events</strong>; no authored-date cutoff is applied to the included commits. Release drivers are shown separately. Co-participation does not establish direct collaboration.${e(eligibleNote)}</p>
    <div class="primary-facts">${stat(f(model.eligible),'Comparable releases')}${stat(f(model.mine),'Releases with '+myName)}${stat(f(model.withPartners),'Other contributors sharing ≥1 release')}</div>
    <div class="primary-controls"><label>Rank connections ${select('primary-together-sort',[{value:'shared',label:'Most shared releases'},{value:'overlap',label:'Greatest overlap (Jaccard)'}],ui.coReleaseSort)}</label><label>Inspect a contributor ${select('primary-together-partner',[{value:'',label:'Select a contributor'},...model.partners.map(row=>({value:row.id,label:row.name}))],chosen?.id||'')}</label></div>
    ${sorted.length?`<div class="primary-co-release-list">${sorted.slice(0,16).map(row=>`<button type="button" class="primary-co-release-row ${row.id===chosen?.id?'active':''}" data-action="primary-co-release-partner" data-person="${e(row.id)}" aria-pressed="${row.id===chosen?.id}"><span><strong>${e(row.name)}</strong><small>${p(row.ofMine)} of ${e(myName)}'s contributing releases</small></span>${bar(row.shared,Math.max(1,sorted[0]?.shared||0))}<strong>${f(row.shared)}</strong><small>shared</small></button>`).join('')}</div>${sorted.length>16?`<p class="primary-muted">Showing 16 of ${f(sorted.length)} connections. Choose any contributor above to inspect their overlap.</p>`:''}`:empty('No shared release contributions',model.mine?'No other contributor authored a change in the same comparable tagged releases.':'This contributor has no authored participation in comparable tagged releases in this window.')}
    ${chosen?`<div id="primary-co-release-detail" class="primary-co-release-detail"><div class="primary-co-release-detail-heading"><div><span class="primary-eyebrow">PAIR EVIDENCE</span><h4>${e(myName)} <span class="primary-co-release-symbol">&amp;</span> ${e(chosen.name)}</h4></div></div><div class="primary-facts">${stat(f(chosen.shared),'Shared releases')}${stat(p(chosen.ofMine),'Of '+myName+' releases')}${stat(p(chosen.ofTheirs),'Of '+chosen.name+' releases')}${stat(p(chosen.overlap),'Jaccard overlap','Shared ÷ releases involving either person')}</div><p class="primary-muted">${e(myName)} appears in ${f(model.mine)} comparable releases; ${e(chosen.name)} appears in ${f(chosen.theirs)}. Shared ÷ union is symmetric. The two conditional percentages have different denominators.</p>
      ${examples.length?`<div class="primary-table-wrap"><table class="primary-co-release-tags"><thead><tr><th>Tag</th><th>Published / tagged</th><th>${e(myName)} commits</th><th>${e(chosen.name)} commits</th><th>Release driver</th></tr></thead><tbody>${examples.slice(0,24).map(r=>`<tr><td>${tagButton(index,r)}</td><td>${e(day(r.date))}</td><td>${f(r.firstCommits)}</td><td>${f(r.secondCommits)}</td><td>${e(r.driverId===focus?myName:r.driverId===chosen.id?chosen.name:r.driverId==null?'Unmatched':index.groups.find(g=>g.id===r.driverId)?.displayName||'Another contributor')}</td></tr>`).join('')}</tbody></table></div>${examples.length>24?`<p class="primary-muted">Latest 24 of ${f(examples.length)} shared releases. Select any tag to inspect the complete release.</p>`:''}`:empty('No shared releases','There are no comparable tagged releases containing authored changes by both contributors.')}</div>`:''}
    <p class="primary-muted">Baseline and incomplete-lineage tags are excluded from comparison; these can inflate apparent overlap. Drivers are credited only when the publisher identity is matched. All percentages are evidence descriptions, not performance assessments.</p>`,'CO-RELEASE PATTERNS');
}
function coReleaseComparison(index, compared, window) {
  const pairs=[];
  for(let i=0;i<compared.length;i++)for(let j=i+1;j<compared.length;j++){
    const a=compared[i],b=compared[j];
    const row=coReleasePatterns(index,a.id,window).partners.find(x=>x.id===b.id);
    if(row)pairs.push({a,b,row});
  }
  if(!pairs.length)return '';
  return card('Who appears in releases together?',`<p class="primary-muted">Pairwise participation across the same comparable incremental tagged releases. The overlap measure is symmetric (shared releases ÷ the union); conditional percentages reveal how often each person appears with the other.</p><div class="primary-table-wrap"><table class="primary-compare-table"><thead><tr><th>Pair</th><th>Shared</th><th>Overlap</th><th>Of first</th><th>Of second</th><th>Evidence</th></tr></thead><tbody>${pairs.map(({a,b,row})=>`<tr><th>${e(a.name)} + ${e(b.name)}</th><td>${f(row.shared)}</td><td>${p(row.overlap)}</td><td>${p(row.ofMine)}</td><td>${p(row.ofTheirs)}</td><td><a class="primary-inline-link" href="${href(index,{view:'contributors',person:index.groups.find(g=>g.id===a.id)?.emails?.[0],partner:index.groups.find(g=>g.id===b.id)?.emails?.[0],tab:'together'})}" data-action="primary-open-co-release-pair" data-first="${e(a.id)}" data-second="${e(b.id)}">Inspect tags ↗</a></td></tr>`).join('')}</tbody></table></div><p class="primary-muted">Co-release means shared delivery participation, not proof of collaboration or code-review interaction.</p>`,'SHARED DELIVERY');
}
function contributorView(index,ui){
  const full={from:index.bounds.min,to:index.bounds.max};
  const window=ui.contributorRange==='period' ? {from:ui.periodFrom,to:ui.periodTo} : ui.contributorRange==='year' ? windowOf(index,365) : full;
  const focus=index.groups.find(g=>g.id===ui.contributorFocus)?.id??index.groups[0]?.id;
  if(focus==null)return empty('No reconciled contributors','Import authored history to explore individual profiles.');
  const person=contributorPortrait(index,focus,window);
  const options=index.groups.map(g=>({value:g.id,label:g.displayName}));
  const mode=ui.contributorTab||'delivery';
  const involvement=person.involvement.slice(0,28);
  const selectedIds=unique([focus,ui.compareB,ui.compareC].filter(id=>index.groups.some(g=>g.id===id)));
  const compared=selectedIds.map(id=>contributorPortrait(index,id,window)).filter(Boolean);
  const tab=(id,label)=>`<button type="button" data-action="primary-contributor-tab" data-tab="${id}" class="${mode===id?'active':''}" aria-pressed="${mode===id}">${label}</button>`;
  const months=person.months;
  const yearRows=[...months.reduce((m,row)=>{const y=row.key.slice(0,4);if(!m.has(y))m.set(y,{year:y,commits:0,releases:0,driven:0,areas:0,months:0});const a=m.get(y);a.commits+=row.commits;a.releases+=row.releases;a.driven+=row.driven;a.months++;a.areas=Math.max(a.areas,row.areas);return m;},new Map()).values()];
  const maxCommits=Math.max(1,...months.map(m=>m.commits));
  const areas=person.profile.areas.slice(0,12),maxAreas=Math.max(1,...areas.map(x=>x[1]));
  return `${chrome('03 / CONTRIBUTOR PORTRAIT','How does someone contribute?')}<p class="primary-lede">A reconciled person's release portfolio, technical footprint, authored rhythm and changing involvement. Not a productivity ranking.</p>
    ${card('Select a contributor',`<div class="primary-controls"><label>Contributor ${select('primary-contributor-focus',options,focus)}</label><label>Observation window ${select('primary-contributor-range',[{value:'all',label:'Entire imported history'},{value:'year',label:'Latest 365 days'},{value:'period',label:'Selected Period Explorer window'}],ui.contributorRange)}</label><button type="button" class="button outline" data-action="primary-contributor-tab" data-tab="compare">Compare people ↗</button></div><p class="primary-muted">${e(window.from)} to ${e(window.to)} · activity uses authored dates; release involvement uses release-event dates. ${person.emails.length} merged author identities.</p>`,'PERSON & SCOPE')}
    <div class="primary-person-hero"><span class="primary-eyebrow">CONTRIBUTOR PORTFOLIO</span><h3>${e(person.name)}</h3><p>${e(person.emails.slice(0,4).join(' · '))}${person.emails.length>4?` · +${person.emails.length-4} more`:''}</p><div class="primary-facts">${stat(f(person.contributed),'Releases contributed to',`${p(person.participation)} of observed releases`)}${stat(f(person.driven),'Releases driven','Matched publishers/taggers')}${stat(f(person.shippedCommits),'Distinct released commits','Deduplicated across tags')}${stat(f(person.distinctAreas),'Areas authored in window')}</div></div>
    <nav class="primary-tabs" aria-label="Contributor perspective">${tab('delivery','Delivery')}${tab('together','Together')}${tab('focus','Focus')}${tab('behaviour','Behaviour')}${tab('evolution','Evolution')}${tab('compare','Compare')}</nav>
    ${mode==='delivery' ? `${card('Release portfolio',`<div class="primary-row between"><p class="primary-muted">Driving and authorship are independent roles. Participation share uses all tag events in the same date window.</p><a class="primary-inline-link" href="${href(index,{view:'observatory'})}" data-action="primary-nav" data-to="observatory">View release landscape ↗</a></div><div class="primary-release-list">${involvement.map(r=>{const m=r.members.find(m=>m.id===focus);return `<a href="${href(index,{view:'observatory',release:r.hash})}" class="primary-release-entry" data-action="primary-open-release" data-hash="${e(r.hash)}"><span class="primary-release-symbol">${r.driver.groupId===focus?'◆':'●'}</span><strong>${e(r.tag)}</strong><small>${e(day(r.date))}</small><span>${m?.commits||0} commits</span><span>${m?.commits?p(m?.share/100):'—'} share</span><em>${r.driver.groupId===focus?'Drove release':'Contributed'}</em></a>`;}).join('')||empty('No release involvement in this period','This person may still have authored activity; driver mappings can also be reviewed in Explore Evidence.')}</div>${person.involvement.length>28?`<p class="primary-muted">Latest 28 of ${person.involvement.length} involvements; use Observatory to navigate the complete tag history.</p>`:''}`,'DELIVERED CONTRIBUTIONS')}${card('Delivery context',`<div class="primary-facts">${stat(f(person.both),'Drove & contributed')}${stat(person.concentration==null?'—':`${f(person.concentration)}%`,'Median share when contributing')}${stat(f(person.driverWithOthers),'Median contributors in releases driven')}</div>${caption('These describe different roles and recorded contributions. Commit share is not a measure of effort, ownership or customer value.')}<button type="button" class="button outline" data-action="primary-contributor-tab" data-tab="together">See who ships alongside them →</button>`,'ROLE COMPOSITION')}` : ''}
    ${mode==='together'?coReleasePanel(index,focus,window,ui):''}
    ${mode==='focus'?`${card('Where authored work happened',`<div class="primary-ranked">${areas.map(([area,value])=>`<div class="primary-ranked-row"><a href="${href(index,{view:'codebase',area})}" data-action="primary-open-area" data-area="${e(area)}">${e(area)}</a>${bar(value,maxAreas)}<strong>${f(value)} touches</strong></div>`).join('')||empty('No file-touch evidence','This person has no matching authored changes in the selected window.')}</div><p class="primary-muted">Areas use top-level path grouping. A file touch is not exclusive ownership. Explore an area to see other contributors and releases.</p>`,'CODEBASE REACH')}`:''}
    ${mode==='behaviour'?`${card('Recorded working rhythm',`<div class="primary-facts">${stat(f(person.profile.commits),'Commits in window')}${stat(f(person.profile.activeDays),'Active author dates')}${stat(person.medianGap==null?'—':`${f(person.medianGap)} days`,'Typical internal quiet interval')}${stat(person.maxGap==null?'—':`${f(person.maxGap)} days`,'Longest internal quiet interval')}</div>${weekHeatmap(person.slots,{shape:true})}<p class="primary-muted">A gap means no matching authored records in this import. It does not establish that the person was not working. Hourly data uses the author-local timestamp, and untimed records are excluded only from the grid.</p><button type="button" class="button outline" data-action="primary-open-rhythm">Open detailed activity, pulse and seasonality ↗</button>`,'AUTHORED ACTIVITY')}`:''}
    ${mode==='evolution'?`${card('Contribution journey',`<p class="primary-muted">Monthly lanes distinguish authored commits (author clock), releases contributed to and releases driven (delivery clock). Select a month to inspect its period evidence.</p><div class="primary-journey-scroll"><div class="primary-journey-track">${months.map(m=>`<a href="${href(index,{view:'periods',from:`${m.key}-01`,to:monthEnd(m.key)})}" data-action="primary-open-month" data-month="${e(m.key)}" title="${e(`${m.key}: ${m.commits} commits, ${m.releases} contributed releases, ${m.driven} driven`)}"><span class="primary-journey-volume"><i style="height:${m.commits>0?clamp(6+94*m.commits/maxCommits,6,100):0}%"></i></span><span class="primary-journey-mark">${m.releases?'●':'·'}</span><span class="primary-journey-mark driven">${m.driven?'◆':'·'}</span><small>${e(m.key)}</small></a>`).join('')}</div></div><div class="primary-legend-row"><span>▥ Authored</span><span>● In releases</span><span>◆ Drove</span></div><div class="primary-table-wrap"><table><thead><tr><th>Year</th><th>Authored commits</th><th>Releases contributed</th><th>Releases driven</th><th>Months in window</th></tr></thead><tbody>${yearRows.map(r=>`<tr><th><a href="${href(index,{view:'periods',from:`${r.year}-01-01`,to:`${r.year}-12-31`})}" data-action="primary-open-year" data-year="${r.year}">${r.year} ↗</a></th><td>${f(r.commits)}</td><td>${f(r.releases)}</td><td>${f(r.driven)}</td><td>${r.months} / 12</td></tr>`).join('')}</tbody></table></div><p class="primary-muted">Partial years are labelled by months included in the selected window; their totals are not automatically annualised.</p>`,'EVOLUTION OVER TIME')}`:''}
    ${mode==='compare'?`${card('Compare people on equal terms',`<p class="primary-muted">All people below use exactly the same time window, Git policy and release-event population. Different numbers are not automatically better or worse.</p><div class="primary-controls"><label>Person A ${select('primary-compare-a',options,focus)}</label><label>Person B ${select('primary-compare-b',[{value:'',label:'Choose another contributor'},...options],ui.compareB)}</label><label>Person C (optional) ${select('primary-compare-c',[{value:'',label:'None'},...options],ui.compareC)}</label></div><div class="primary-table-wrap"><table class="primary-compare-table"><thead><tr><th>Evidence dimension</th>${compared.map(x=>`<th>${e(x.name)}</th>`).join('')}</tr></thead><tbody>${[
      ['Releases contributed',x=>f(x.contributed)],['Release participation',x=>p(x.participation)],['Releases driven',x=>f(x.driven)],['Authored commits',x=>f(x.profile.commits)],['Authored active dates',x=>f(x.profile.activeDays)],['Distinct codebase areas',x=>f(x.distinctAreas)],['Median internal quiet days',x=>f(x.medianGap)],
    ].map(([label,get])=>`<tr><th>${e(label)}</th>${compared.map(x=>`<td>${e(get(x))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="primary-comparison-heats">${compared.map(x=>`<div class="primary-inset"><strong>${e(x.name)}</strong>${weekHeatmap(x.slots,{shape:true})}</div>`).join('')}</div><p class="primary-muted">Each timing grid shows share of that individual's timed commits; equal greens indicate similar composition, not equal volume. Underlying counts and denominators remain visible.</p>`,'INDIVIDUAL COMPARISON')}${coReleaseComparison(index,compared,window)}`:''}
    ${deploymentContributorPanel(index,focus,ui)}
    ${card('Follow their contribution',`<p class="primary-muted">Move from this portrait into the same person's authored period, release anatomy or component history, preserving an investigation trail.</p><div class="primary-card-footer"><a class="button soft" href="${href(index,{view:'periods',from:windowOf(index,30).from,to:windowOf(index,30).to,person:index.groups.find(g=>g.id===focus)?.emails?.[0]})}" data-action="primary-person-period" data-person="${e(focus)}">Explore their recent period →</a><button class="button outline" type="button" data-action="primary-evidence-person" data-person="${e(focus)}">Inspect every activity chart ↗</button></div>`,'FOLLOW THE EVIDENCE')}`;
}

function codebaseView(index,ui){
  const window=ui.codebaseRange==='period'?{from:ui.periodFrom,to:ui.periodTo}:{from:index.bounds.min,to:index.bounds.max};
  const model=codebasePortrait(index,window,ui.codeArea);
  const chosen=model.areas.find(a=>a.area===ui.codeArea)||(ui.codeArea?null:model.areas[0]);
  const max=Math.max(1,...model.areas.map(a=>a.touches));
  let authoredPanel='';
  if(ui.codebaseRange==='period'){
    const commits=index.activity.filter(c=>c.date>=window.from&&c.date<=window.to);
    const counts=new Map();
    for(const c of commits)for(const file of c.files)counts.set(file.area,(counts.get(file.area)||0)+1);
    const areas=[...counts].sort((a,b)=>b[1]-a[1]);
    const focus=ui.codeArea?commits.filter(c=>c.files.some(file=>file.area===ui.codeArea)):[];
    const people=new Map();
    for(const c of focus)for(const file of c.files)if(file.area===ui.codeArea)people.set(c.groupId,(people.get(c.groupId)||0)+1);
    const contributors=[...people].sort((a,b)=>b[1]-a[1]);
    authoredPanel=card('Authored work in the selected period',`<p class="primary-muted">${e(window.from)}–${e(window.to)} · Authored-date activity, including changes that are not part of a tagged release in this window. Select an area to investigate its authorship.</p><div class="primary-ranked">${areas.slice(0,15).map(([name,value])=>`<div class="primary-ranked-row"><button type="button" data-action="primary-select-area" data-area="${e(name)}" class="${name===ui.codeArea?'primary-emphasis':''}">${e(name)}</button>${bar(value,Math.max(1,...areas.map(x=>x[1])))}<strong>${f(value)} touches</strong></div>`).join('')||empty('No authored changes','No matching commit records in this interval.')}</div>${ui.codeArea?`<div class="primary-inset"><h4>${e(ui.codeArea)} · ${f(focus.length)} authored commits</h4><div class="primary-ranked">${contributors.slice(0,12).map(([id,touches])=>`<div class="primary-ranked-row">${whoButton(index,id)}${bar(touches,Math.max(1,...contributors.map(x=>x[1])))}<strong>${f(touches)} touches</strong></div>`).join('')||'<p>No recorded authorship in this area for these dates.</p>'}</div><details class="primary-notes"><summary>Inspect matching commits (${f(focus.length)} · latest 30)</summary><div class="primary-commit-list">${focus.sort((a,b)=>b.date.localeCompare(a.date)).slice(0,30).map(c=>`<div><code>${e(c.hash.slice(0,8))}</code><span>${e(c.date)}</span>${whoButton(index,c.groupId)}<span>${e(c.subject)}</span></div>`).join('')||'No matching commits.'}</div></details></div>`:''}`,'AUTHOR-DATE FOOTPRINT');
  }
  return `${chrome('THE CODEBASE','Follow changes through the code.')}<p class="primary-lede">Explore released changes, their recorded contributors, and related commits. File co-occurrence does not establish ownership or direct collaboration.</p>
    ${card('Set the observation clock',`<div class="primary-row"><label>Scope ${select('primary-codebase-range',[{value:'all',label:'All released history'},{value:'period',label:'Selected Period Explorer window'}],ui.codebaseRange)}</label></div><p class="primary-muted">A release-event period means releases published in that window; authored changes in that window are displayed separately, not silently treated as shipped.</p>`,'SCOPE & PROVENANCE')}
    ${authoredPanel}
    ${card('Released codebase areas',`<div class="primary-ranked">${model.areas.slice(0,22).map(a=>`<div class="primary-ranked-row"><button type="button" class="${a.area===chosen?.area?'primary-emphasis':''}" data-action="primary-select-area" data-area="${e(a.area)}">${e(a.area)}</button>${bar(a.touches,max)}<strong>${f(a.touches)} touches</strong><small>${a.releases} releases</small></div>`).join('')||empty('No matching tagged changes','No release events containing file touches have been observed in this window. Authored work may still appear above.')}</div>`,'RELEASED CODEBASE REACH')}
    ${chosen?card(`${chosen.area} · released area portrait`,`<div class="primary-facts">${stat(f(chosen.touches),'Released file touches')}${stat(f(chosen.releases),'Tagged releases')}${stat(f(chosen.people.length),'Contributors')}</div><div class="primary-two-col"><div class="primary-inset"><h4>People who touched this area</h4>${chosen.people.slice(0,12).map(([id,v])=>`<div class="primary-ranked-row">${whoButton(index,id)}${bar(v,Math.max(1,...chosen.people.map(x=>x[1])))}<strong>${f(v)}</strong></div>`).join('')}</div><div class="primary-inset"><h4>Recent releases containing this area</h4>${chosen.versions.slice(0,12).map(r=>`<div class="primary-release-brief">${tagButton(index,r)}</div>`).join('')}</div></div><p class="primary-muted">Area names come from top-level Git paths. Counts may overlap across authors and releases; no ownership is inferred.</p>`,'RELEASED FOOTPRINT'):ui.codeArea?empty('No released changes for this area','The selected area may have authored activity without a matching release event in this period. Look at its authored footprint above.'):''}`;
}

export function renderPrimaryExplorer(index,ui){
  if(!index)return empty('Preparing repository history','Building complete-release and authored-date evidence.');
  let content;
  if(ui.mode==='periods')content=periodExplorer(index,ui);
  else if(ui.mode==='contributors')content=contributorView(index,ui);
  else if(ui.mode==='codebase')content=codebaseView(index,ui);
  else if(ui.mode==='deployments')content=deploymentExplorer(index,ui);
  else content=observatory(index,ui);
  return `<div class="primary-explorer">
    <div class="primary-topline"><div><span class="primary-kicker-dot"></span><span class="primary-eyebrow">REPOSITORY EVIDENCE / ${e(ui.mode.toUpperCase())}</span></div><div class="primary-top-actions"><button class="primary-back" data-action="primary-back" type="button" title="Browser Back also works">← Back</button><a class="primary-inline-link" href="${href(index,{view:'deployments'})}" data-action="primary-nav" data-to="deployments">Deployments ↗</a><a class="primary-inline-link" href="${href(index,{view:'codebase'})}" data-action="primary-nav" data-to="codebase">Codebase ↗</a></div><div class="primary-link-actions"><a class="primary-inline-link" href="${href(index,{view:ui.mode, ...({observatory:{release:ui.releaseHash},periods:{from:ui.periodFrom,to:ui.periodTo},contributors:{person:index.groups.find(g=>g.id===ui.contributorFocus)?.emails?.[0],tab:ui.contributorTab},deployments:{event:ui.deploymentFocus,environment:ui.deploymentEnv},codebase:{area:ui.codeArea}}[ui.mode]||{})})}" title="Open in new tab using the browser">Open this view in a new tab ↗</a><button type="button" class="primary-inline-link" data-action="local-copy-url">Copy page link</button></div></div>
    ${content}
    <footer class="primary-footnote">${e(filterSentence(index))}. Tag ancestry determines release contents; authored dates determine personal activity. Activity is not effort, value or working hours. Baseline releases, incomplete refs, squashes and unmatched publishers require interpretation.</footer>
  </div>`;
}
export function periodBriefingForUi(index,ui){
  const window={from:ui.periodFrom,to:ui.periodTo};
  const base=briefingText(index,periodDigest(index,window,{comparison:ui.periodComparison,customComparison:{from:ui.compareFrom,to:ui.compareTo}}));
  return `${base}\n${deploymentBriefing(index,window.from,window.to)}`;
}
